/*!
 * Themeasy — Social Share Row
 *
 * Drives the .tms-social-share-row widget.
 *
 * - Opens a popup window (opener cleared after opening) for non-mailto network links
 * - Copies the current share URL to the clipboard via the async Clipboard API,
 *   with a textarea fallback for older / non-secure contexts
 * - Animates a transient toast for copy success/failure
 * - Idempotent (binds each element once); safe to re-init from the Elementor
 *   editor preview
 *
 * Namespace:    window.Themeasy.socialShareRow
 * Pattern:      IIFE + onDomReady() + boot()
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.socialShareRow = window.Themeasy.socialShareRow || {}

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  /**
   * Defense-in-depth scheme allowlist mirroring esc_url(). The PHP already
   * sanitizes the share URL, but the JS refuses to navigate to anything that
   * is not http(s)/mailto/tel or a relative path.
   *
   * @param {string} url - Candidate URL.
   * @returns {boolean}
   */
  function isSafeUrl(url) {
    return typeof url === 'string' && /^(https?:|mailto:|tel:|\/|#)/i.test(url)
  }

  /**
   * Open a popup window for a share intent, with a graceful tab fallback when
   * the popup is truly blocked.
   *
   * NOTE: `noopener` is intentionally NOT passed in the features string — per
   * spec, `window.open()` returns `null` whenever `noopener` is set, which
   * makes block-detection impossible and turns every successful popup into a
   * spurious same-tab redirect. We null the `opener` reference manually right
   * after the popup is created to preserve the same security guarantee. The
   * anchor that triggered the click also carries `rel="noopener noreferrer"`
   * as a no-JS fallback (see the PHP render method).
   *
   * @param {string} url - Target URL.
   */
  function openShareWindow(url) {
    if (!url || !isSafeUrl(url)) return

    const width = 600
    const height = 540
    const top = Math.max(0, (window.outerHeight - height) / 2 + (window.screenY || 0))
    const left = Math.max(0, (window.outerWidth - width) / 2 + (window.screenX || 0))
    const features = [
      'width=' + width,
      'height=' + height,
      'top=' + Math.round(top),
      'left=' + Math.round(left)
    ].join(',')

    const popup = window.open(url, '_blank', features)

    if (popup) {
      try { popup.opener = null } catch (e) { /* cross-origin — ignore */ }
      return
    }

    // Popup actually blocked — fall back to a regular navigation in the same tab.
    window.location.href = url
  }

  /**
   * Detect whether the widget is being rendered inside the Elementor editor
   * preview iframe. Inside the editor every click must stay inert: opening a
   * share popup would navigate the iframe (and the email/custom anchors would
   * leave the editor entirely).
   *
   * @returns {boolean}
   */
  function isElementorEditMode() {
    return !!(
      window.elementorFrontend &&
      typeof window.elementorFrontend.isEditMode === 'function' &&
      window.elementorFrontend.isEditMode()
    )
  }

  /**
   * Try the modern async Clipboard API first; fall back to a hidden textarea
   * + execCommand for non-secure contexts (e.g. local network HTTP).
   *
   * @param {string} text - String to copy.
   * @returns {Promise<boolean>} resolves true on success, false on failure.
   */
  function copyToClipboard(text) {
    if (!text) return Promise.resolve(false)

    if (window.navigator && window.navigator.clipboard && window.isSecureContext) {
      return window.navigator.clipboard.writeText(text).then(
        function () { return true },
        function () { return legacyCopy(text) }
      )
    }

    return Promise.resolve(legacyCopy(text))
  }

  function legacyCopy(text) {
    let ok

    try {
      const textarea = document.createElement('textarea')
      textarea.value = text
      textarea.setAttribute('readonly', '')
      textarea.style.position = 'absolute'
      textarea.style.left = '-9999px'
      textarea.style.top = '0'

      document.body.appendChild(textarea)
      textarea.select()
      textarea.setSelectionRange(0, textarea.value.length)

      ok = document.execCommand('copy')

      document.body.removeChild(textarea)
    } catch (e) {
      ok = false
    }

    return ok
  }

  // ------------------------------------------------------------------------
  // Toast helper (one shared timer per wrapper)
  // ------------------------------------------------------------------------
  const toastTimers = new WeakMap()

  function showToast(wrapper, message, durationSec) {
    const toast = wrapper.querySelector('.tms-social-share-row__toast')
    if (!toast || !message) return

    const textNode = toast.querySelector('.tms-social-share-row__toast-text') || toast

    textNode.textContent = message
    toast.hidden = false

    // Force layout flush so the transition runs reliably even when re-shown
    // before the prior timer expires.
    void toast.offsetWidth
    toast.classList.add('tms-social-share-row__toast--visible')

    const existingTimer = toastTimers.get(wrapper)
    if (existingTimer) {
      window.clearTimeout(existingTimer)
    }

    const ms = Math.max(500, Math.round((durationSec || 2.5) * 1000))

    const timer = window.setTimeout(function () {
      toast.classList.remove('tms-social-share-row__toast--visible')

      // Hide once the fade-out finishes so it doesn't trap pointer events.
      window.setTimeout(function () {
        if (!toast.classList.contains('tms-social-share-row__toast--visible')) {
          toast.hidden = true
        }
      }, 250)

      toastTimers.delete(wrapper)
    }, ms)

    toastTimers.set(wrapper, timer)
  }

  // ------------------------------------------------------------------------
  // Wrapper-level bind (idempotent)
  // ------------------------------------------------------------------------
  function bindWrapper(wrapper) {
    if (!wrapper || wrapper.dataset.tmsSocialShareRowBound === 'true') return

    wrapper.dataset.tmsSocialShareRowBound = 'true'

    // Share URL is resolved at render time and carried via data attribute so
    // the JS does not need to know about WordPress permalinks.
    const shareUrl = wrapper.getAttribute('data-share-url') || ''
    const shareText = wrapper.getAttribute('data-share-text') || ''
    const copyOk = wrapper.getAttribute('data-copy-ok') || 'Link copied'
    const copyErr = wrapper.getAttribute('data-copy-error') || 'Could not copy'
    const duration = parseFloat(wrapper.getAttribute('data-toast-duration') || '2.5')

    // Pre-compute network URLs once. The PHP also writes valid hrefs as a
    // no-JS fallback; on click we intercept and open a popup instead.
    const intents = buildIntents(shareUrl, shareText)

    wrapper.addEventListener('click', function (event) {
      const item = event.target.closest('.tms-social-share-row__item')
      if (!item || !wrapper.contains(item)) return

      // In the Elementor editor every click is inert. The anchor hrefs are
      // already neutralised (`#`) by content_template, but we still need to
      // swallow the click so it never reaches openShareWindow / copy and
      // never bubbles into a page jump.
      if (isElementorEditMode()) {
        event.preventDefault()
        return
      }

      const network = item.getAttribute('data-network') || ''

      if (network === 'copy') {
        event.preventDefault()

        copyToClipboard(shareUrl).then(function (ok) {
          showToast(wrapper, ok ? copyOk : copyErr, duration)
        })

        return
      }

      // Email opens in the user's mail client — no popup, no preventDefault.
      if (network === 'email' || network === 'custom') {
        return
      }

      if (intents[network]) {
        event.preventDefault()
        openShareWindow(intents[network])
      }
    })
  }

  function buildIntents(shareUrl, shareText) {
    const url = encodeURIComponent(shareUrl || '')
    const text = encodeURIComponent(shareText || '')
    const message = shareText
      ? encodeURIComponent(shareText + ' ' + shareUrl)
      : url

    return {
      x: 'https://twitter.com/intent/tweet?url=' + url + (shareText ? '&text=' + text : ''),
      facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + url,
      linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + url,
      whatsapp: 'https://api.whatsapp.com/send?text=' + message
    }
  }

  // ------------------------------------------------------------------------
  // Public API
  // ------------------------------------------------------------------------

  /**
   * Initialize Social Share Row instances inside the given root (defaults to
   * the whole document).
   *
   * @param {HTMLElement|Document} [root] - Optional scope element.
   */
  window.Themeasy.socialShareRow.init = function (root) {
    const scope = root || document
    const wrappers = scope.querySelectorAll('.tms-social-share-row')

    if (!wrappers.length) return

    wrappers.forEach(bindWrapper)
  }

  /**
   * Clear the bound flag for instances inside the given root so init() can
   * re-bind after the Elementor editor re-renders the widget.
   *
   * @param {HTMLElement|Document} [root] - Optional scope element.
   */
  window.Themeasy.socialShareRow.reset = function (root) {
    const scope = root || document
    const wrappers = scope.querySelectorAll('.tms-social-share-row')

    wrappers.forEach(function (wrapper) {
      delete wrapper.dataset.tmsSocialShareRowBound

      const toast = wrapper.querySelector('.tms-social-share-row__toast')
      if (toast) {
        toast.classList.remove('tms-social-share-row__toast--visible')
        toast.hidden = true
      }

      const existingTimer = toastTimers.get(wrapper)
      if (existingTimer) {
        window.clearTimeout(existingTimer)
        toastTimers.delete(wrapper)
      }
    })
  }

  function boot() {
    if (document.querySelector('.tms-social-share-row')) {
      window.Themeasy.socialShareRow.init()
    }
  }

  window.Themeasy.socialShareRow.boot = boot

  // Auto-initialize on DOM ready.
  onDomReady(function () {
    window.Themeasy.socialShareRow.boot()
  })

})(window, document)
